import{_ as a,o as t,c as i,a3 as s}from"./chunks/framework.DAK02U1-.js";const k=JSON.parse('{"title":"从源码构建","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"从源码构建 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/catter/dev/build"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/catter/dev/build"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/dev/build"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/dev/build"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/dev/build"}]]},"headers":[],"relativePath":"zh/catter/dev/build.md","filePath":"zh/catter/dev/build.md","lastUpdated":1792989239000}'),r={name:"zh/catter/dev/build.md"};function l(n,e,o,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="从源码构建" tabindex="-1">从源码构建 <a class="header-anchor" href="#从源码构建" aria-label="Permalink to &quot;从源码构建&quot;">​</a></h1><h2 id="前置要求" tabindex="-1">前置要求 <a class="header-anchor" href="#前置要求" aria-label="Permalink to &quot;前置要求&quot;">​</a></h2><ul><li><a href="https://pixi.sh" target="_blank" rel="noreferrer">pixi</a> -- 环境与依赖管理</li><li><a href="https://xmake.io/" target="_blank" rel="noreferrer">XMake</a> -- 构建系统（pixi 不会安装，需单独安装）</li><li>Git</li></ul><h2 id="支持的平台" tabindex="-1">支持的平台 <a class="header-anchor" href="#支持的平台" aria-label="Permalink to &quot;支持的平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>工具链</th></tr></thead><tbody><tr><td>Linux (linux-64)</td><td>GCC 14.2</td></tr><tr><td>macOS (osx-arm64)</td><td>xclang 23.1.3</td></tr><tr><td>Windows (win-64)</td><td>xclang 23.1.3，构建 MinGW</td></tr><tr><td>Windows on ARM（win-64，模拟运行）</td><td>xclang 23.1.3，构建 ARM64 的 MinGW</td></tr></tbody></table><p>Windows 上用 <a href="https://github.com/clice-io/xclang" target="_blank" rel="noreferrer">xclang</a> 构建 MinGW 版本（<code>x86_64-w64-mingw32</code>）；<code>pixi run cfg debug arm64</code> 则配置为构建 ARM64 版本（<code>aarch64-w64-mingw32</code>），可以在 Windows on ARM 上进行，也可以在 x64 Windows 上进行，只是 x64 Windows 运行不了构建出的程序。每次 Windows 构建都会同时构建另一种架构的钩子 DLL，x64 和 ARM64 两个都有。</p><h2 id="构建命令" tabindex="-1">构建命令 <a class="header-anchor" href="#构建命令" aria-label="Permalink to &quot;构建命令&quot;">​</a></h2><p>所有构建通过 pixi 任务管理：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Configure the build (mode: debug, release, or releasedbg)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cfg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build the project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Configure in release mode</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cfg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span></span></code></pre></div><h2 id="构建系统" tabindex="-1">构建系统 <a class="header-anchor" href="#构建系统" aria-label="Permalink to &quot;构建系统&quot;">​</a></h2><p>项目使用 <a href="https://xmake.io/" target="_blank" rel="noreferrer">XMake</a> 作为构建系统，通过 pixi 任务管理。C++ 标准为 C++23。</p><h3 id="构建目标" tabindex="-1">构建目标 <a class="header-anchor" href="#构建目标" aria-label="Permalink to &quot;构建目标&quot;">​</a></h3><ul><li><code>catter</code> -- 主 CLI 可执行文件（DECISION 守护进程）</li><li><code>catter-proxy</code> -- 代理进程管理器</li><li><code>catter-hook-unix</code> -- Unix 钩子共享库（Linux/macOS）</li><li><code>catter-hook-x64</code>、<code>catter-hook-arm64</code> -- Windows 钩子 DLL，每种架构一个，Windows 上的每次构建都会同时生成两者</li><li><code>support</code>、<code>command</code>、<code>session</code>、<code>capture</code>（以及 <code>capture-inject</code>）、<code>protocol</code>、<code>feature</code> -- 静态库，<code>src/</code> 下每个目录一个</li></ul><h2 id="主要依赖" tabindex="-1">主要依赖 <a class="header-anchor" href="#主要依赖" aria-label="Permalink to &quot;主要依赖&quot;">​</a></h2><ul><li><a href="https://github.com/gabime/spdlog" target="_blank" rel="noreferrer">spdlog</a> (1.15.3) -- 日志</li><li><a href="https://github.com/clice-io/kotatsu" target="_blank" rel="noreferrer">kotatsu</a> -- 异步运行时、测试框架、选项解析</li><li><a href="https://github.com/microsoft/Detours" target="_blank" rel="noreferrer">Microsoft Detours</a> -- Windows API 钩子与 DLL 注入（仅 Windows）</li></ul>`,15)])])}const u=a(r,[["render",l]]);export{k as __pageData,u as default};
